- }`,
    new: `  // common.h
  __attribute__((target("sse4.2")))
  inline u32 crc32c_hw(const void* data, size_t n, u32 crc) {   // 7.5 GB/s，一页 0.6 µs
      const unsigned char* p = (const unsigned char*)data;
      unsigned long long c = ~(unsigned long long)crc;
